using System.Collections.Generic;
using UnityEngine;

namespace ImagineVR
{
    /// <summary>
    /// The library assets the third version of the language brought: articulated vehicles that drive
    /// and fly, buildings to line streets with, and the props games are made of. They are written as
    /// lists of parts in the same language `make` reads (Resources/LibraryV3.json, generated by
    /// scripts/library_v3.py, where each can be drawn to a picture and checked), and built by the
    /// same code, so wheels roll and rotors spin through the one mechanism. Registered in the order
    /// scripts/catalog_additions.json lists them, which is the order Catalog.Export writes.
    /// </summary>
    public static partial class Library
    {
        static partial void RegisterThirdVersion()
        {
            TextAsset text = Resources.Load<TextAsset>("LibraryV3");
            if (text == null) { Debug.LogWarning("ImagineVR: Resources/LibraryV3.json is missing; the third version's assets are not in the library"); return; }
            if (!(MiniJson.Parse(text.text) is List<object> entries)) return;
            foreach (object item in entries)
            {
                if (!(item is Dictionary<string, object> entry)) continue;
                Statement e = Statement.Wrap(entry);
                var parts = e.ObjList("parts");
                bool tool = e.Str("kind") == "tool";
                Vector3 grip = e.Vec("grip", Vector3.zero);
                AssetDef def = Add(e.Str("id"), e.Str("category", "props"), e.Num("size", 1f), e.Str("desc", ""), string.Join(",", e.StrList("tags")), string.Join(",", e.StrList("aliases")),
                    mb =>
                    {
                        mb.Shade(0.04f);
                        if (tool) mb.Push(Vector3.zero, new Vector3(-90f, 0f, 0f)).Push(-grip);
                        Maker.BuildParts(mb, parts);
                        if (tool) mb.Pop().Pop();
                    }).New();
                foreach (string flag in e.StrList("flags"))
                {
                    switch (flag)
                    {
                        case "tool": def.AsTool(); break;
                        case "hold": def.Hold(); break;
                        case "ball": def.Ball(e.Num("mass", 0.3f), e.Num("bounce", 0.6f)); break;
                        case "solid": def.Solid(e.Num("mass", 5f), e.Num("bounce", 0.2f), e.Str("collider") == "sphere" ? ColliderShape.Sphere : e.Str("collider") == "capsule" ? ColliderShape.Capsule : ColliderShape.Box); break;
                        case "floats": def.Floats(); break;
                        case "flies": def.Flies(); break;
                    }
                }
                if (e.Has("drive")) def.Drives(e.Str("drive"));
                if (e.TryVec3("seat", out Vector3 seat)) def.SeatAt(seat);
                Dictionary<string, object> strike = e.Obj("strike");
                if (strike != null) def.Strikes(Statement.Wrap(strike).Num("power", 1.2f), Statement.Wrap(strike).Num("loft", 0f));
                Dictionary<string, object> fires = e.Obj("fires");
                if (fires != null)
                {
                    Statement f = Statement.Wrap(fires);
                    def.HasMuzzle = true;
                    def.Muzzle = f.Vec("muzzle", new Vector3(0f, 1f, 2f));
                    def.ShotSound = f.Str("sound", "boom");
                    def.FireEvery = f.Num("every", 0.5f);
                    def.Automatic = f.Flag("auto");
                    def.ShotSpeed = f.Num("speed", 40f);
                    def.ShotSize = f.Num("size", 1f);
                    def.Damage = f.Num("damage", 2f);
                    def.Blast = f.Num("blast", 0f);
                    def.ShotLife = 4f;
                    if (f.TryColor("color", out Color c)) def.Shoots(c);
                    if (tool) def.Behavior = "blaster";
                }
            }
        }

        /// <summary>Clubs, bats and rackets of the first library get a strike: how hard and high they send a ball.</summary>
        static void StrikersOfTheFirstLibrary()
        {
            Asset("golf_club")?.Strikes(1.5f, 16f);
            Asset("baseball_bat")?.Strikes(1.3f, 10f);
            Asset("tennis_racket")?.Strikes(1.15f, 6f);
        }
    }
}
